insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"AWAY_ZERO","title":"¿El visitante termina en cero?","description":"Se corrige con el marcador final.","category":"defensiva","difficulty":"expert","points":8,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"away_eq","n":0},"priority":0,"cooldown":2,"tags":["defensiva"]},{"code":"HOME_GTE_2","title":"¿El local anota al menos 2?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_gte","n":2},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"HOME_GTE_3","title":"¿El local anota 3 o más?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_gte","n":3},"priority":0,"cooldown":2,"tags":["marcador"]},{"code":"HOME_GTE_4","title":"¿El local anota 4 o más?","description":"Se corrige con el marcador final.","category":"marcador","difficulty":"medium","points":4,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"home_gte","n":4},"priority":0,"cooldown":2,"tags":["marcador"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;